def transform(grid):
    h, w = len(grid), len(grid[0])
    frame = grid[0][0]

    # The left-hand framed area ends at its full-height border.
    left_w = next(
        (c for c in range(1, w) if all(grid[r][c] == frame for r in range(h))),
        w
    )

    # Find horizontal panel separators.
    separators = [
        r for r in range(h)
        if all(grid[r][c] == frame for c in range(left_w))
    ]
    panels = []
    for a, b in zip(separators, separators[1:]):
        if b > a + 1:
            panels.append((a + 1, b))

    # Extract the non-background objects to the right of the frame.
    seen = set()
    objects = []
    for r in range(h):
        for c in range(left_w + 1, w):
            color = grid[r][c]
            if color == 0 or color == frame or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for nr, nc in ((rr - 1, cc), (rr + 1, cc),
                               (rr, cc - 1), (rr, cc + 1)):
                    if (0 <= nr < h and left_w < nc < w
                            and (nr, nc) not in seen
                            and grid[nr][nc] == color):
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            minr = min(x for x, _ in cells)
            minc = min(y for _, y in cells)
            shape = frozenset((x - minr, y - minc) for x, y in cells)
            objects.append((color, shape))

    out = [row[:left_w] for row in grid]
    used = set()

    for top, bottom in panels:
        coords = [
            (r, c)
            for r in range(top, bottom)
            for c in range(1, left_w - 1)
            if grid[r][c] != frame
        ]
        if not coords:
            continue
        minr = min(r for r, _ in coords)
        minc = min(c for _, c in coords)
        target = frozenset((r - minr, c - minc) for r, c in coords)

        for i, (color, shape) in enumerate(objects):
            if i not in used and shape == target:
                used.add(i)
                for r, c in coords:
                    out[r][c] = color
                break

    return out
